/**
 * Arbitrary JSON workflow input contract. Use this instead of typed workflow inputs when a workflow should accept one free-form JSON payload.
 *
 */
export type WorkflowArbitraryJson = {
    description?: string;
    default_payload?: JsonValue;
};

export type WorkflowInputs = {
    [key: string]: WorkflowInputSchema;
};

export type WorkflowEdge = {
    source: WorkflowNodeName;
    target: WorkflowNodeName;
    branch_label: string;
    condition_summary: string;
};

export type WorkflowNode = {
    name: WorkflowNodeName;
    instructions: string;
    goal: string;
    done_criteria: string;
    preferred_skills?: Array<string>;
    preferred_tools?: Array<string>;
};

export type WorkflowSummary = {
    workflow_name: WorkflowName;
    title: string;
    summary: string;
    updated_at: string;
};

export type UpdateWorkflowScheduleRequest = {
    schedule: string;
    time_zone?: string;
    inputs?: JsonValue;
    timeout_seconds: number;
    suspend?: boolean;
    successful_runs_history_limit?: number;
    failed_runs_history_limit?: number;
};

export type CreateWorkflowScheduleRequest = {
    name: WorkflowScheduleName;
    schedule: string;
    time_zone?: string;
    inputs?: JsonValue;
    timeout_seconds: number;
    suspend?: boolean;
    successful_runs_history_limit?: number;
    failed_runs_history_limit?: number;
};

export type WorkflowWebhookTrigger = {
    workflow_name: WorkflowName;
    api_key_id: ApiKeyId;
    last_triggered_at: string;
};

/**
 * Better Auth API key identifier.
 */
export type ApiKeyId = string;

export type WorkflowRunSummary = {
    name: WorkflowRunName;
    workflow_name: WorkflowName;
    trigger_type: WorkflowRunTriggerType;
    schedule_name?: WorkflowScheduleName;
    timeout_seconds: number;
    status: WorkflowRunStatus;
    reason: string;
    created_at: string;
    started_at?: string;
    completed_at?: string;
    duration_seconds?: number;
};

export type WorkflowRunInputs = JsonValue;

export type EvaluationEvidenceReference = {
    /**
     * Zero-based index into the evidence findings.
     */
    evidence_index: number;
    session_id: string;
    message_id: string;
    /**
     * The native part ID, when citing a tool call.
     */
    part_id?: string;
};

export type EvaluationJudgment = {
    correctness: number;
    efficiency: number;
    summary: string;
    evidence: Array<string>;
    limitations: Array<string>;
    references?: Array<EvaluationEvidenceReference>;
};

export type EvaluationReferences = {
    tokens: number;
    tool_calls: number;
};

export type EvaluationTranscriptSession = {
    session_id: string;
    session: Session;
    messages: Array<{
        info: Message;
        parts: Array<Part>;
    }>;
};

export type EvaluationExecution = {
    model: EvaluationModel;
    run_name: string;
    state: 'queued' | 'running' | 'judging' | 'completed' | 'error' | 'cancelled';
    run_status?: WorkflowRunStatus;
    run_reason?: string;
    run?: WorkflowRunDetail;
    message?: string;
    session_id?: string;
    /**
     * Complete native session messages and metadata, including delegated sessions. Never truncated or summarized.
     */
    transcript?: Array<EvaluationTranscriptSession>;
    measured_efficiency?: number;
    tokens?: number;
    tool_calls?: number;
    duration_seconds?: number;
    judgment?: EvaluationJudgment;
    /**
     * The judge continued after native context compaction. Informational only; does not affect scoring.
     */
    judge_context_compacted?: boolean;
    score?: number;
};

export type EvaluationModel = {
    provider_id: string;
    model_id: string;
    label: string;
    variant?: string;
};

export type WorkflowEvaluationSummary = {
    id: string;
    judge: EvaluationModel;
    executions: Array<EvaluationExecution>;
    state: WorkflowEvaluationState;
    created_at: string;
};

export type WorkflowEvaluationState = 'queued' | 'running' | 'cancelling' | 'completed' | 'cancelled';

export type WorkflowEvaluation = {
    id: string;
    request: WorkflowEvaluationRequest;
    workflow: Workflow;
    executions: Array<EvaluationExecution>;
    state: WorkflowEvaluationState;
    message?: string;
    created_at: string;
    updated_at: string;
    scoring_version: 'trace-v1';
    references?: EvaluationReferences;
};

export type Workflow = {
    agent_name: AgentName;
    workflow_name: WorkflowName;
    title: string;
    summary: string;
    inputs?: WorkflowInputs;
    arbitrary_json?: WorkflowArbitraryJson;
    nodes: Array<WorkflowNode>;
    edges: Array<WorkflowEdge>;
    created_at: string;
    updated_at: string;
};

export type WorkflowEvaluationRequest = {
    id: string;
    inputs: JsonValue;
    models: Array<EvaluationModel>;
    judge: EvaluationModel;
    /**
     * Optional judging instructions or expected workflow output. Sent only to the judge.
     */
    judge_instructions?: string;
    /**
     * Maximum execution time for each workflow run, in seconds.
     */
    timeout_seconds: number;
    /**
     * Maximum number of executions running or awaiting judgment in this evaluation. Each slot is held until judging finishes.
     */
    concurrency: number;
};

